          "title": "Stage 1",
          "indicator": "Opponent attempts to punch your face from within your guard",
          "essentialDetail": "Effective head control and inside arm positioning",
          "mostCommonMistake": "Expending too much energy",
          "badGuyReminder": null,
          "safetyTip": null,
          "corePrinciples": [
            "Posture (16)",
            "Head Control (28)"
          ],
