          "sliceNumber": 1,
          "title": "Basic Application",
          "indicator": "Opponent extends their arm towards you",
          "essentialDetail": "Effective pull and cutoff step",
          "mostCommonMistake": "Lifting up rather than driving down with your ribcage",
